-- >>> Hand-written (not generated by drizzle-kit; keep it when regenerating).
-- Marks the uploads that existing content mentions as used, so the worker
-- keeps them (apps/server/src/files/storage.ts, markFilesUsed).
UPDATE "files" SET "used_at" = now()
WHERE "used_at" IS NULL AND "id" IN (
  SELECT (regexp_matches("content", '/files/([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})', 'g'))[1]::uuid
  FROM (
    SELECT "markdown" AS "content" FROM "page_revisions"
    UNION ALL SELECT "markdown" FROM "pages"
    UNION ALL SELECT "markdown" FROM "change_set_items"
    UNION ALL SELECT "description" FROM "change_sets"
    UNION ALL SELECT "body" FROM "change_set_events"
    UNION ALL SELECT "markdown" FROM "drafts"
    UNION ALL SELECT "description" FROM "spaces"
    UNION ALL SELECT "page_types"::text FROM "spaces"
  ) AS "texts"
  WHERE "content" LIKE '%/files/%'
);--> statement-breakpoint
-- The app no longer keeps the identity provider's tokens after the sign-in
-- check; remove those that earlier versions stored in plaintext.
UPDATE "accounts" SET "access_token" = NULL, "refresh_token" = NULL, "id_token" = NULL
WHERE "access_token" IS NOT NULL OR "refresh_token" IS NOT NULL OR "id_token" IS NOT NULL;
-- <<< End of hand-written SQL.
